+package net.sf.mpxj.common;
+
+import java.io.File;
+import java.io.FileOutputStream;
+import java.io.IOException;
+import java.io.InputStream;
+import java.io.OutputStream;
+import java.util.zip.ZipEntry;
+import java.util.zip.ZipFile;
+
+public final class ZipUtils
+{
+   private ZipUtils()
+   {
+      // utility
+   }
+
+   /**
+    * Safely create a File for a zip entry contained within a target directory.
+    * This canonicalizes paths and verifies the resulting file is contained
+    * within the provided base directory to prevent path traversal (zip slip).
+    *
+    * @param baseDir target extraction directory (must exist or be creatable)
+    * @param entryName name of the zip entry
+    * @return canonical File instance for the entry within baseDir
+    * @throws IOException if the entry would be extracted outside baseDir or IO fails
+    */
+   private static File safeCreateFile(File baseDir, String entryName) throws IOException
+   {
+      if (entryName == null)
+      {
+         throw new IOException("Null entry name");
+      }
+
+      if (entryName.indexOf('\0') != -1)
+      {
+         throw new IOException("Entry name contains null byte");
+      }
+
+      // Explicitly reject absolute entry names (e.g. "/etc/passwd" or "C:\windows")
+      File entryAsFile = new File(entryName);
+      if (entryAsFile.isAbsolute())
+      {
+         throw new IOException("Absolute paths are not allowed: " + entryName);
+      }
+
+      // Construct the destination file relative to the base dir and canonicalize both
+      File dest = new File(baseDir, entryName);
+      File canonicalBase = baseDir.getCanonicalFile();
+      File canonicalDest = dest.getCanonicalFile();
+
+      String basePath = canonicalBase.getPath();
+      String destPath = canonicalDest.getPath();
+
+      // Ensure the destination path starts with the base path + separator (to avoid prefix bypass)
+      if (!destPath.startsWith(basePath + File.separator) && !destPath.equals(basePath))
+      {
+         throw new IOException("Entry is outside of the target dir: " + entryName);
+      }
+
+      return canonicalDest;
+   }
+
+   public static void extractEntry(ZipFile zipFile, ZipEntry entry, File targetDir) throws IOException
+   {
+      String name = entry.getName();
+
+      // Create target dir if necessary
+      if (!targetDir.exists() && !targetDir.mkdirs())
+      {
+         throw new IOException("Unable to create target directory: " + targetDir);
+      }
+
+      File outFile = safeCreateFile(targetDir, name);
+
+      if (entry.isDirectory())
+      {
+         if (!outFile.exists() && !outFile.mkdirs())
+         {
+            throw new IOException("Unable to create directory: " + outFile);
+         }
+         return;
+      }
+
+      File parent = outFile.getParentFile();
+      if (parent != null && !parent.exists() && !parent.mkdirs())
+      {
+         throw new IOException("Unable to create directory: " + parent);
+      }
+
+      try (InputStream in = zipFile.getInputStream(entry);
+           OutputStream out = new FileOutputStream(outFile))
+      {
+         byte[] buffer = new byte[8192];
+         int len;
+         while ((len = in.read(buffer)) != -1)
+         {
+            out.write(buffer, 0, len);
+         }
+      }
+   }
+}
