+// Allow only a conservative subset of characters for app ids.
+// Reject path separators and traversal sequences to prevent escaping
+// the intended applicationData directory (important on Windows).
+const SAFE_APPID_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,28}[A-Za-z0-9_.-]$/;
+
+function validateAppId(appid) {
+  if (typeof appid !== 'string') return false;
+
+  // Reject any path separator or traversal tokens
+  if (appid.indexOf('/') !== -1 || appid.indexOf('\\') !== -1) return false;
+  if (appid.indexOf('..') !== -1) return false;
+
+  // Preserve the original length constraint semantics (reject empty and very long ids)
+  if (appid.length === 0 || appid.length >= 30) return false;
+
+  // Restrict to a safe character set to prevent other filesystem semantics (e.g. drive letters)
+  if (!SAFE_APPID_RE.test(appid)) return false;
+
+  return true;
+}
