+// Heading renderer for QMarkdown
+// Ensure heading text is safely escaped when rendering into HTML.
+// This fixes an XSS where raw header text could include markup that was
+// interpreted even when markdown's html/no-html option was set to false.
+module.exports = function renderHeading(tokens, idx, options, env, self) {
+  const token = tokens[idx];
+
+  // Small, safe HTML-escaping helper. We avoid pulling in external
+  // dependencies to keep the change minimal and predictable.
+  const escapeHtml = (str) => {
+    if (str == null) return '';
+    return String(str)
+      .replace(/&/g, '&amp;')
+      .replace(/</g, '&lt;')
+      .replace(/>/g, '&gt;')
+      .replace(/"/g, '&quot;')
+      .replace(/'/g, '&#39;');
+  };
+
+  // Prefer rendering children tokens if available (this preserves
+  // inline formatting like emphasis). If no children are present, fall
+  // back to escaping token.content.
+  let content = '';
+  if (token.children && token.children.length) {
+    // Use the provided inline renderer which will respect markdown-it
+    // options (including the html/no-html setting). However, some
+    // environments rendered raw HTML elsewhere; to be safe we still
+    // escape the result if HTML is not enabled.
+    try {
+      content = self.renderInline(token.children, options, env);
+    } catch (e) {
+      // Fallback to raw content escape if inline rendering fails.
+      content = escapeHtml(token.content || '');
+    }
+  } else {
+    content = escapeHtml(token.content || '');
+  }
+
+  // If markdown's html option is disabled ensure we do not output raw HTML.
+  // Some callers may pass options.html === true to allow raw HTML.
+  if (!options || !options.html) {
+    content = escapeHtml(content);
+  }
+
+  return `<${token.tag}>${content}</${token.tag}>`;
+};
