+import React, { useRef, useEffect } from "react";
+import { Embeddable } from "../../types";
+
+type Props = {
+  embeddable: Embeddable;
+};
+
+// Escape text for HTML insertion (text node / title)
+function escapeHtml(text: string | undefined): string {
+  if (!text) return "";
+  return String(text)
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#39;");
+}
+
+// Build a safe srcdoc string by serializing the embed payload into a JS
+// literal (via JSON.stringify) and applying it in a controlled manner.
+// This avoids inserting untrusted HTML directly into the document.
+function buildSafeSrcDoc(payload: unknown, title?: string): string {
+  const serialized = JSON.stringify(payload);
+  // The script reads the payload and inserts untrusted textual content
+  // using textContent to ensure no HTML is interpreted. If the embed
+  // actually needs to render arbitrary HTML, that should be done within
+  // a controlled renderer in the embed target and explicitly allowed.
+  return `<!doctype html>
+<meta charset="utf-8">
+<title>${escapeHtml(title)}</title>
+<div id="excalidraw-embed-root"></div>
+<script>
+  (function(p){
+    try{
+      var root = document.getElementById('excalidraw-embed-root');
+      // Example payload keys: html, text, etc. Prefer textContent insertion.
+      if (p && typeof p === 'object') {
+        // If the embed provides explicit textual content, render it safely.
+        if (typeof p.text === 'string') {
+          root.textContent = p.text;
+        } else if (typeof p.html === 'string') {
+          // Do not insert provided HTML verbatim. If html is provided we
+          // sanitize by treating it as text (prevent HTML parsing).
+          root.textContent = p.html;
+        } else {
+          // fallback: pretty-print the payload
+          root.textContent = JSON.stringify(p);
+        }
+      } else {
+        root.textContent = String(p);
+      }
+    }catch(e){
+      // swallow to avoid breaking parent page
+    }
+  })(${serialized});
+</script>`;
+}
+
+export default function Embed({ embeddable }: Props) {
+  const iframeRef = useRef<HTMLIFrameElement | null>(null);
+
+  useEffect(() => {
+    if (!iframeRef.current) {
+      return;
+    }
+
+    // Construct srcdoc ourselves rather than using embeddable.srcdoc verbatim.
+    // This prevents stored XSS via injected HTML/attributes.
+    // Determine sandbox flags: only allow same-origin when the embed
+    // explicitly requires it (principle of least privilege).
+    const requiresSameOrigin = Boolean(
+      // Feature gate: check an explicit flag on the embeddable object.
+      // Default to false if not present.
+      (embeddable as any).requiresSameOrigin
+    );
+
+    const sandboxFlags = requiresSameOrigin
+      ? "allow-scripts allow-same-origin"
+      : "allow-scripts";
+
+    // Build srcdoc safely from embeddable.payload (avoid raw HTML).
+    const payload = (embeddable as any).payload ?? { text: (embeddable as any).text ?? "" };
+    iframeRef.current.srcdoc = buildSafeSrcDoc(payload, embeddable.title);
+
+    // Set sandbox attribute explicitly (do not use dangerouslySetInnerHTML).
+    iframeRef.current.setAttribute("sandbox", sandboxFlags);
+
+    // Set a safe title attribute (escape control handled by DOM API when using setAttribute).
+    if (typeof embeddable.title === "string") {
+      iframeRef.current.setAttribute("title", embeddable.title);
+    } else {
+      iframeRef.current.removeAttribute("title");
+    }
+  }, [embeddable]);
+
+  return (
+    <iframe
+      ref={iframeRef}
+      // Initial attributes are minimal; use effect to populate the rest.
+      style={{ width: "100%", height: "100%", border: 0 }}
+    />
+  );
+}
