+package org.apache.streampipes.util;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+
+/**
+ * Minimal URL validator used to mitigate SSRF when fetching remote pipeline elements.
+ *
+ * Validation rules:
+ * - Only allow http and https schemes.
+ * - Host must be present.
+ * - Resolve the hostname and reject any resolved IP that is:
+ *   - loopback, any-local, link-local, multicast, or site-local
+ *   - IPv6 unique local (fc00::/7) or fe80::/10 link-local
+ *
+ * This is an allowlist-style validation that rejects addresses in internal ranges.
+ */
+public final class UrlValidator {
+
+  private UrlValidator() {
+  }
+
+  public static void validateUrl(String url) {
+    if (url == null) {
+      throw new IllegalArgumentException("URL must not be null");
+    }
+
+    final URI uri;
+    try {
+      uri = new URI(url);
+    } catch (URISyntaxException e) {
+      throw new IllegalArgumentException("Invalid URL: " + e.getMessage(), e);
+    }
+
+    String scheme = uri.getScheme();
+    if (scheme == null) {
+      throw new IllegalArgumentException("URL must have a scheme (http or https)");
+    }
+
+    String lowerScheme = scheme.toLowerCase();
+    if (!"http".equals(lowerScheme) && !"https".equals(lowerScheme)) {
+      throw new IllegalArgumentException("Only http and https schemes are allowed");
+    }
+
+    String host = uri.getHost();
+    if (host == null || host.isEmpty()) {
+      // This rejects protocol-relative URLs and other odd forms.
+      throw new IllegalArgumentException("URL must specify a host");
+    }
+
+    try {
+      InetAddress[] addrs = InetAddress.getAllByName(host);
+      for (InetAddress addr : addrs) {
+        if (addr.isAnyLocalAddress()
+            || addr.isLoopbackAddress()
+            || addr.isLinkLocalAddress()
+            || addr.isMulticastAddress()
+            || addr.isSiteLocalAddress()) {
+          throw new IllegalArgumentException("URL resolves to a prohibited internal address");
+        }
+
+        String addrStr = addr.getHostAddress();
+        if (addrStr != null) {
+          String lower = addrStr.toLowerCase();
+          // IPv6 unique local addresses (fc00::/7) begin with "fc" or "fd"
+          if (lower.startsWith("fc") || lower.startsWith("fd")) {
+            throw new IllegalArgumentException("URL resolves to a prohibited internal IPv6 address");
+          }
+          // IPv6 link-local addresses begin with "fe80"
+          if (lower.startsWith("fe80")) {
+            throw new IllegalArgumentException("URL resolves to a prohibited internal IPv6 address");
+          }
+          // Explicit IPv6 loopback
+          if ("::1".equals(lower)) {
+            throw new IllegalArgumentException("URL resolves to loopback address");
+          }
+        }
+      }
+    } catch (Exception e) {
+      // Treat DNS resolution failures conservatively as invalid inputs.
+      throw new IllegalArgumentException("Unable to resolve host or host is not allowed: " + e.getMessage(), e);
+    }
+  }
+}
