+/**
+ * Safely read the request body into a Buffer.
+ *
+ * Protects against situations where the client closes the connection
+ * (req.aborted / socket destroyed) and ensures we don't try to write
+ * a response after the request has already been closed.
+ */
+export function readRequestBody(req: IncomingMessage, res: ServerResponse): Promise<Buffer> {
+  return new Promise((resolve, reject) => {
+    // If the request was already aborted/closed, bail out early.
+    if (req.aborted || (req.socket && req.socket.destroyed)) {
+      return reject(new Error('request aborted'));
+    }
+
+    const chunks: Buffer[] = [];
+
+    // If Content-Length header explicitly set to 0, resolve immediately with empty buffer.
+    // This avoids waiting for 'end' events that may never come for certain clients.
+    const contentLength = req.headers['content-length'];
+    if (typeof contentLength === 'string' && contentLength.trim() === '0') {
+      return resolve(Buffer.alloc(0));
+    }
+
+    // Track whether the request ended/aborted to avoid sending responses after close.
+    let finished = false;
+
+    function cleanup() {
+      req.removeListener('data', onData);
+      req.removeListener('end', onEnd);
+      req.removeListener('error', onError);
+      req.removeListener('aborted', onAborted);
+    }
+
+    function onData(chunk: Buffer | string) {
+      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk)));
+    }
+
+    function onEnd() {
+      finished = true;
+      cleanup();
+      try {
+        resolve(Buffer.concat(chunks));
+      } catch (err) {
+        reject(err);
+      }
+    }
+
+    function onAborted() {
+      finished = true;
+      cleanup();
+      reject(new Error('request aborted'));
+    }
+
+    function onError(err: Error) {
+      finished = true;
+      cleanup();
+      reject(err);
+    }
+
+    req.on('data', onData);
+    req.on('end', onEnd);
+    req.on('error', onError);
+    req.on('aborted', onAborted);
