+/**
+ * Safely serializes a value for embedding into generated TypeScript/JavaScript
+ * source. Using JSON.stringify avoids injecting raw content into the output
+ * file and ensures strings are properly escaped.
+ */
+const safeSerializeForCode = (value: unknown): string => JSON.stringify(value);
+
+export const getEnumImplementation = (
+  name: string,
+  values: Array<string | number>,
+  schema?: any,
+) => {
+  const enumName = pascal(name);
+
+  const enumValues = values
+    .map((v) => {
+      const key = typeof v === 'string' ? v : String(v);
+      const safeKey = key.replace(/[^a-zA-Z0-9_]/g, '_');
+      return `  ${safeKey} = ${JSON.stringify(v)},`;
