+/**
+ * Sanitize and validate a Content-Type header value.
+ *
+ * Accept only a single mime-type token (type/subtype) optionally followed by
+ * parameters (e.g. "text/plain; charset=utf-8"). Return the lower-cased
+ * "type/subtype" portion. Reject values that do not match the expected
+ * mime-type grammar to avoid treating attacker-controlled header values as
+ * executable or otherwise unsafe input.
+ */
+export function sanitizeContentType(contentType?: string | string[] | null): string | undefined {
+  if (!contentType) {
+    return undefined;
+  }
+
+  // If header is an array (multiple Content-Type headers), reject as invalid.
+  if (Array.isArray(contentType)) {
+    throw new BadRequestException('Invalid Content-Type header');
+  }
+
+  // Trim whitespace.
+  const ct = contentType.trim();
+
+  // Allow only ASCII token characters for type and subtype per RFC 2045/2616.
+  // This pattern accepts "type/subtype" and optional parameters after a semicolon.
+  const mimeRegex = /^([A-Za-z0-9!#$&^_.+\-]+)\/([A-Za-z0-9!#$&^_.+\-]+)(?:\s*;.*)?$/;
+  const match = mimeRegex.exec(ct);
+  if (!match) {
+    // Be conservative: do not allow malformed values through.
+    throw new BadRequestException('Invalid Content-Type header');
+  }
+
+  // Return canonicalized lower-case type/subtype without parameters.
+  return `${match[1].toLowerCase()}/${match[2].toLowerCase()}`;
+}
+
+export default sanitizeContentType;
